        for k,v in cs.items():
            if len(v)==2 and len(k)>1 and frozenset(v[0][1]) in chc or len(v)==2 and len(k)>1 and frozenset(v[1][1]) in chc:
                m0,m1=v
                def ncorner(cl): return min(math.dist(p,(cy,cx)) for p in cl for cy,cx in [(0,0),(0,W-1),(H-1,0),(H-1,W-1)])
                def ncenter(cl): return min(math.dist(p,((H-1)/2,(W-1)/2)) for p in cl)
                votes={'corner_farthest': m0 if ncorner(m0[1])>ncorner(m1[1]) else m1,
                       'corner_nearest' : m0 if ncorner(m0[1])<ncorner(m1[1]) else m1,
                       'center_farthest': m0 if ncenter(m0[1])>ncenter(m1[1]) else m1,
                       'center_nearest' : m0 if ncenter(m0[1])<ncenter(m1[1]) else m1}
                for n,mm in votes.items():
                    ok=frozenset(mm[1]) in chc
                    res[n]+=ok; 
