def rotkey(cl):
    pts=[(r-min(r for r,_ in cl), c-min(c for _,c in cl)) for r,c in cl]
    variants=[]
    for f in [lambda p:p, lambda p:(p[1],p[0]), lambda p:(-p[1],p[0]), lambda p:(p[1],-p[0]),
              lambda p:(-p[0],p[1]), lambda p:(p[0],-p[1]), lambda p:(-p[0],-p[1]), lambda p:(-p[1],-p[0])]:
        v=sorted(f(p) for p in pts)
        m=(min(r for r,c in v), min(c for r,c in v))
        variants.append(tuple((r-m[0],c-m[1]) for r,c in v))
    return min(variants)

def classes_of2(din, rot_inv):
    bg_,objs_=components(din)
    keyf = (lambda cl: rotkey(cl)) if rot_inv else skey
    from collections import defaultdict as dd
    D=dd(list)
    for cc,cl in objs_:
        D[(cc,keyf(cl))].append(cl)
    return {k:v for k,v in D.items() if len(v)==2}

def predict(din, arrow_cl, rot_inv, metric):
    # near = min distance member pair class to arrow; changed = far member -> arrow color
    acol=din[arrow_cl[0][0]][arrow_cl[0][1]]
    acen=sum(p[0] for p in arrow_cl)/len(arrow_cl), sum(p[1] for p in arrow_cl)/len(arrow_cl)
    best=None
    for (cc,key),mem in classes_of2(din,rot_inv).items():
        ds=[]
        for m in mem:
            cen=sum(p[0] for p in m)/len(m), sum(p[1] for p in m)/len(m)
            if metric=='mind': dd_=min(math.hypot(a-c,b-d) for a,b in m for c,d in arrow_cl)
            else: dd_=math.hypot(cen[0]-acen[0],cen[1]-acen[1])
            ds.append(dd_)
        i=int(ds[0]>ds[1])
        nearv=ds[1-i]
        if best is None or nearv<best[0]: best=(nearv, mem[i], cc)
    if best is None: return None
    return [(r,c,acol) for r,c in best[1]]

