def thinL(cl):
    rs=[r for r,_ in cl]; cs_=[c for _,c in cl]
    if len(cl)==max(max(rs)-min(rs)+1, max(cs_)-min(cs_)+1): return False
    S=set(cl)
    for (r,c) in cl:
        if ((r+1,c) in S or (r-1,c) in S) and ((r,c+1) in S or (r,c-1) in S): return True
    return False

